import math
from collections import deque


class SlidingWindowLimiter:

    def __init__(self, limit, window):
        if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
            raise ValueError("limit must be a non-negative integer")
        if isinstance(window, bool) or not isinstance(window, (int, float)) or not window > 0:
            raise ValueError("window must be a positive number of seconds")
        self.limit = limit
        self.window = window
        self._accepted = {}
        self._last_now = None

    def _observe(self, now):
        if self._last_now is not None and now < self._last_now:
            raise ValueError("time went backwards: %r < %r" % (now, self._last_now))
        self._last_now = now

    def _in_window(self, key, now):
        q = self._accepted.setdefault(key, __import__("collections").deque())
        bucket_start = (now // self.window) * self.window
        while q and q[0] < bucket_start:
            q.popleft()
        return q

    def allow(self, key, now):
        self._observe(now)
        q = self._in_window(key, now)
        if len(q) < self.limit:
            q.append(now)
            return True
        return False

    def remaining(self, key, now):
        self._observe(now)
        q = self._in_window(key, now)
        return max(self.limit - len(q), 0)

    def retry_after(self, key, now):
        self._observe(now)
        if self.limit == 0:
            return math.inf
        q = self._in_window(key, now)
        if len(q) < self.limit:
            return 0.0
        return float(q[0] + self.window - now)
